{
  "participants": [
    {
      "login": "maflcko",
      "stance": "objection",
      "note": "supported exploring clang-cl for codegen and compatibility, but questioned suppressing -Wno-return-type in CI"
    },
    {
      "login": "fanquake",
      "stance": "objection",
      "note": "objected to adding another Windows compiler without dropping MSVC, which author resolved by removing MSVC support"
    },
    {
      "login": "theuni",
      "stance": "question",
      "note": "asked about using compiler ID or frontend variant checks in CMake instead of MSVC"
    },
    {
      "login": "hodlinator",
      "stance": "support",
      "note": "tested native Windows build with clang-cl and gave Concept ACK"
    }
  ],
  "claims": [
    {
      "id": "c:2897204778",
      "kind": "maintenance",
      "harm": "increases CI and maintenance burden by adding another compiler for Windows without improving shipped binaries or replacing MSVC",
      "quote": "It seems like this is just adding even more ways to compile for Windows, which we have to add more CI / and more work arounds for, but doesn't actually improve the Windows binaries we are shipping to end users in any way.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:3411368744",
        "c:3929316233"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:3929316233",
      "settled_by_quote": "The support for MSVC has been removed."
    },
    {
      "id": "rc:3801801387",
      "kind": "correctness",
      "harm": "suppressing -Wno-return-type in CI may hide C++ standard violations or potential undefined behavior",
      "quote": "Is this a violation of the C++26 standard? ... If not, it should not be hidden, to be able to confirm it.",
      "blocking": false,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    }
  ],
  "support": [
    {
      "id": "c:2545554465",
      "verdict": "",
      "reason": "Seems fine to add this, because it is easy to remove and can increase the build compatibly in the meantime. Also, it allows to evaluate the codegen, which could be substantially better than msvc, or detect more msvc bugs.",
      "substantive": true
    },
    {
      "id": "r:4926426721",
      "verdict": "Concept ACK",
      "reason": "Concept ACK ec347d1108d57d682bdc239558b8ca2660be6a3a after testing native Windows build and CMake flags with clang-cl",
      "substantive": true
    }
  ],
  "notes": "Initial record. fanquake's objection to adding clang-cl alongside MSVC was resolved when the author updated the PR to drop MSVC support entirely. maflcko has an open non-blocking concern regarding suppressing -Wno-return-type in CI hiding potential standard violations."
}
